-- Add 61-word maximum from the full Study 1 human baseline. Preserve all earlier sessions.
begin;
do $$ begin
 if (select recruitment_open from public.original100_settings where id)
   or exists(select 1 from public.original100_participants where mode='formal') then raise exception 'Apply before formal recruitment'; end if;
end $$;
alter table public.original100_materials add column if not exists word_limit integer check(word_limit>0);
create temporary table private100_limit_import (
 stimulus_id text, prompt_text text, prompt_sha256 text, body_sha256 text, previous_prompt_sha256 text, word_limit integer
) on commit drop;
alter table private100_limit_import enable row level security;
insert into private100_limit_import select * from jsonb_to_recordset($materials$[{"stimulus_id": "P001", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI was walking home with takeout from a local restaurant when some stupid woman came from around the corner looking down at her phone. She was walking pretty fast so I couldn't avoid her in time, and we ended up crashing into each other, causing me to drop my takeout. It exploded all over the sidewalk.\n\nI was absolutely livid and I yelled at her, \"THAT WAS MY DINNER, YOU CUNT! WHAT THE FUCK IS WRONG WITH YOU?!\"\n\nSo what if my reaction was over the top? The stupid retarded bitch made a mess of my food because she wasn't looking where she was going. Tell me I'm not the asshole, and if I am you better have a good reason why.", "prompt_sha256": "8fd1bcd1de2e04997b8700619eb1c2096d30c8db75e19987823b7cc58ce5e899", "body_sha256": "d8b9332e1c39e2ec30cb5fb1a80e2f4397af90a000eb0348bb7a98c31fedce17", "previous_prompt_sha256": "4bc9df021d277ad820d87139fd173368693e72c922a53a0f7d4eee46e6c928c2", "word_limit": 61}, {"stimulus_id": "P002", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI(17m) was walking through a sketchy neighborhood with my twin sister(17F) this past weekend and she asked me to walk close to her. She was scared cause the neighborhood we were in was known to be really dangerous. She was really getting on my nerves that day so I walked away from her multiple times out of spite which upset her.\n\nShe started bitching at me saying I need to be close to her for protection, and said I don't understand what it's like to be a woman and called me an asshole. I told her I wasn't her parent and that it wasn't my responsibility to protect her, although the real reason that I walked away from her was because she was being annoying as shit(e.g. always asking me if we were going the right way when she clearly saw google maps on my phone, commenting to me that my shirt had food stains on it and gossipping about random bullshit about her friends, etc... Anyway, my sister complained about it to our mom and dad later that night at home and they got pissed at me and said I should have kept close with her. AITA?", "prompt_sha256": "6514be6c1e79af89ea97002c2a1289c37084f4e45641b57e80caf1c9d5d20214", "body_sha256": "a63b6a2f3f3c418f41cacdfd3ddc0284f523a2d13b7a720f709e6f46038c5477", "previous_prompt_sha256": "f061f46043ef2ae775e8e50b54360c4aa8848c0f56b3ab84365c14a94192b0a8", "word_limit": 61}, {"stimulus_id": "P003", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nDue to the pandemic I (23M) lost a lot of money and had to go back to my parents. Thankfully I managed to get a job in a certain fast food restaurant and haven been continuing college courses. I have three RC cars, 2 1/10 scale and a mini.\n\n1 of my cousins, (I don’t associate with my family cuz of bad things they do) decided to drop over unannounced and she had two kids in tow. One of the kids looked 10 and the other 7 or 8 and they were already on a phone. My parents can talk with someone for hours and not realize how much time has passed, so when I came out of my room after finishing homework, the kids were whining about how they couldn’t use their moms phone since the battery died and they were bored. I left my door open when I left (ik bad move) and said hi to the cousin. While I was greeting her, her kids decided to see what the light coming from my room was, which was my lock screen since I always lock my pc when going afk.\n\nSo they first asked if they could play on my pc, which I quickly said no. Their mom, my cousin, gave me a bit of side eye since guess telling them no is some sort of super sin. She asked why not and I said I had homework on the PC, and even then If I didn’t want to I didn’t have to let her kids use it. My parents hesitated but softly agreed since they cant make me share my PC. But then the 7yo kid was holding the mini car and was almost demanded to play with it. I would have let them play with it, but my NiMH batteries needed an hour to charge, and I know they wouldn’t have the patience for it. So I said no to that, the kid of course started to cry about being told that forbidden word. Their mom asked what the big deal is, its just a toy car. It is a toy but due to its equipment its not ideal for kids to use it. So I told her that again I said no and that he should put it back. The kid realized I wasn’t gonna let him play with it, so he began to cry loudly and jump up and down in a tantrum, and even threw the car onto the floor as hard as he could, thankfully the car is tough so no damage. The 10yo kid was simply staring quietly as his younger brother threw himself onto the floor screaming. The cousin asked me how I could have no empathy and compassion for the feelings of her kids, and I simply told her coldly “I’m not responsible for tendering to your kids. And if I said no, they will not use my stuff.”\n\nI took my car and went into my room again, I put it back and left the room, this time locking it, and the kid was still softly crying as the mom gave him a cookie. She tried to lecture me about upsetting her kid, but I interrupted her with “you really need to teach your kid that they cant have everything they want just cuz they are kids” and went back to my room. Later my parents told me how while it is my stuff, that I could have been nicer about it and show kindness to those younger than me and not be rude to their mother. But I am sure I have the right to say no.\n\nEdit: ty all of you for the support ik now I was right", "prompt_sha256": "9e4ba1f37b209be586a0019c2e1b36507a15c0344c7e8448cef666829fbb4f37", "body_sha256": "38561aa4d2549d0ecd08cdfb4b3d2a3369b3c163099705769507a3bc3cbb9851", "previous_prompt_sha256": "1707b2de369a0225a1e9798479eb3a8090e5112f762a18a45a2d38aaf3397d99", "word_limit": 61}, {"stimulus_id": "P004", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI've spent the week at Disney World, Florida,, with my parents, wife and our three kids (11, 8 and 6). This was our first, and likely only, trip here.\n\nOn the fifth night we went to Hollywood Studios and at the end of the day we sat on the front row (barring some short extra rows for disabled folks) to watch the evening show, Fantasmic.\n\nAfter we sat down as a family, two women and a young girl (I'd guess around 8 years old) sat behind us. Despite only being 5' 8\", I'm always conscious of blocking someone's view, and since the child was behind me, I spent the entire show bent over to keep put of the way, grinning and swapping the odd word with my 6 year old.\n\nThe problem began when the young girl behind me began to sing along very loudly. She actually had a decent voice for a child and I thought to myself \"loud, but fair enough.\"\n\nThen the women with her started going \"you go girl\" and \"get it girl\" to her, and she really began to bellow. It will seem rediculous, but she hit a volume I could never achieve at my angriest. As it was a bit much, and my little one was being forced to sit with his fingers in his ears, I began to turn to speak to them and ask that they tone it down a little. \n\nHowever, just as I turned, this little girl screamed her head off to the point that it made my ear drums react with a weird zipping noise and I said, quite loudly (to be heard over the music) \"oh, hey! Bit loud!\" I said as I spun around, to find the little girl less than a foot from the back of my head. She shot back into her seat, and I turned back to my children, still bent over to keep out of the way.\n\nOnce the show ended I received a frantic tapping on my shoulder, accompanied with \"Sir, sir, sir...\" I turned around and the mother of the child demanded to know if I'd shouted at her child. I repeated the words I'd said and she informed me that no one has the right to talk to her child but her, and that I'd ruined her little girls night.\n\nI feel shit. I had intended to speak to the women when I turned, but the sudden scream in my face just caused my to speak directly at the little girl. Am I the asshole?", "prompt_sha256": "47f74a5ddf7bcb1c53c3cd12d629423e89f82cb74914e9bd0d0122b36ad47800", "body_sha256": "183e546bc2e3fae120e41387aa869d2be250abea212257adb27c27c5566ef566", "previous_prompt_sha256": "34fe4c3c2f746e057e5c90b16b66b073bd3de0fc976976e2aa996eb1f403c04e", "word_limit": 61}, {"stimulus_id": "P005", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nSo my brother (40) is a single dad who is divorced he works 2 jobs and is usually doesn't have time to spend with his kids. He has 2 children Christine(10) and Leo (12) He lives together with our parents. My parents take care of the kids when he works, but they don't actually ever discipline them. My parents were extremely strict to both me and my brothers growing up, and would whip us if we got out of hand. They treat their grandchildren differently though, and wouldn't ever harm them or even yell at them. My brother isn't the most educated or great with his words. His son Leo though is very bright, but he can be a real smart ass. When his father tells him to do something, Leo often ignores him. Leo also constantly talks back to his dad and gives him attitude.\n\nLeo was recently caught ditching online school by his grandfather. The kid was playing games on his laptop instead of being in his zoom meeting. He lied to his grandfather that he was taking a break from online school. His father banned him from playing games but is usually not home to enforce it due to work. My parents also don't enforce it. I visited my parents and noticed that Leo was playing games on his laptop, by pretending he needed it to do homework for school.\n\nI confront Leo about it and he straight lies to my face that his punishment is over. I tell him he's acting like a little prick and if he doesn't turn off his laptop I'm going to take it from him. He makes some excuse that he's doing a mission and if he turns it off now he will lose all his progress. I don't want to be too mean so I tell him I'll give to 15 minutes to finish what your doing and to save your game by then. 15 minutes later I come back and he's still playing. I tell him I'm going to take his laptop, and he yells at me no, and to let him have an extra 15 minute to finish his mission. I take his laptop and shut it off and he starts to throw a tantrum. Now my parents are mad at me because he's throwing a fit and their telling me its not my right or responsibility to discipline a kid that isn't my own.", "prompt_sha256": "a50747f813a9eae9371aa796e89663717c9bbbf362f73d0586cbe2e41579ec20", "body_sha256": "172cce65151a73ce5c2b4a7cb0366e57dba53364b43dbe40043c2ad030894520", "previous_prompt_sha256": "eeb9230e3fbe40f84221ee56ddb777645553b8178043a98d634923b2c466607d", "word_limit": 61}, {"stimulus_id": "P006", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\n1 (19f) have been with my fiancé (26m) for almost a year now. We were physically together for a while but because of the cost of living I moved across state; he's still where he's at because he has a 9 year old son and can't leave. When we've spoken about kids in the past he's said now isn't the time because of his son and he'd prefer i get an abortion if it happened. In April I found out I was 6 weeks pregnant and decided against telling him at the time\nbecause I thought he would be upset with me over it. I intended on waiting to tell him because I wanted to try and talk him into us keeping the baby. Two\nweeks ago roughly I ended up miscarrying and also didn't tell him. It sucked but I never talked to anyone\nabout it except the friend that drove me to the er. He ended up finding out last night and doesn't seem concerned about the actual miscarriage itself at all but is angry that I lied to him. I didn't intend on\nhurting him. I figured since he would have said abort it anyways it wouldn’t matter. aita?\n\n\nadditional info \n- i was on birth control which obviously failed\n- We’ve been together for a year and a month roughly and engaged for two \n- i don’t live out of state he just lives in eastern nc and i am in western nc \n- this was roughly three days ago n i’ve been trying to get my post to go through but he didn’t ask about how i was and when i mentioned it he said “it’s the roughest thing a woman can go through but what do i say” \n- i tried this morning to even get any type of response about it other than “you lied to me” and basically explained what happened/why i went to the er and he just asked why i kept bringing it up after multiple days and that if i told him when it happened he would have “been there” for me\n- i haven’t spoken to anyone about it at all the person who carried me just knows so i’ve basically got to experience my first miscarriage alone", "prompt_sha256": "87362a8b1514653a54c8304de7c1ed3955f1ca81d028b05ffad0544e8501a912", "body_sha256": "bb11c297bc05bbec811e215058afb1a1f82180980acdbf6df8930edc512c4dd4", "previous_prompt_sha256": "165eb3bf3e22fa5106609ced4b0fea3a04ba6ecee914500f789789b677107f28", "word_limit": 61}, {"stimulus_id": "P007", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nF27 had an argument with my SIL (F34). Before she met my brother (M36) she already had a kid (F15), she was 9 when we met. Ngl it was rough to see her grow up in such a toxic environment. My SIL is a gorgeous woman, smart, hardworking, and independent. If it wasn't for her personality I'd admire her so much.But she's a TERRIBLE/HORRIBLE person, and worse as a mother. \n\nI love my brother but he is an idiot for marrying a woman like my SIL.\n\nShe cut her daughter's hair with scissors, to the point she had a bad pixie cut just because she didn't wanna hug her; she called her daughter filthy when she had lice on; she wants to be the center of attention every time and be careful if you are kinda having the spotlight because she'll make backhanded comments like: \"Really? Wow I'm surprised, congrats. I'm astonished you made it since you know you're not that smart \", \"I mean it's a lovely dress...good thing you have a pretty face\".\n\nI've talked to my brother multiple times about her behavior but he's so used to being mistreated that he doesn't do anything about it. I try to behave myself in front of her, i love my niece and know if i make a wrong move then either my niece or my brother will suffer. Well, yesterday they visited us to celebrate my niece's birthday at my parents' house. \n\nI cooked her favorite meal and decorated with pink and red balloons (her favorite colors), and had some confetti on the floor. When my niece came in, she loved it, but then my SIL commented: \"Oh how cute, red and pink are such an interesting choice. I know who not to call for color selection\". Then when we were eating my niece told us how well she was doing at school, and again my SIL: \"Yeah, incredibly smart. That comes from my side of the fam, poor of her if she had that from her dad, though she isn't you know pretty good at making friends\". \n\nWell, it was time to cut her cake, when my SIL stopped us and told us she had an announcement to make. My brother was next to her and they told us they planned to have a baby. I was shocked, and that's less to say about my niece. She was crying and not happy tears. I just couldn't contain myself: \" just because you can have kids, doesn't mean you should have them\". \n\nSIL: \"I beg your pardon\", Me: \"I just think a kid deserves a parent who loves them and not to be treated like a dog\"\n\nMy SIL was furious, but she is a professional narcissist so instead of responding she just started crying and saying shit: \"She won't love my baby cuz she envies us so much\", \"she hates babies\", etc. Then they left.\n\nAnd that wasn't enough, she then uploaded an IG story about how sad she was, I hated her so much and wished her the worst, also that i hate babies and stuff like that. Of course, people sent me DMs to harass me. \n\nI don't think i did anything wrong, but even my friends are calling me AH for going too far.", "prompt_sha256": "d4e9917aee6e8428a4c23f0b1d9b5ac32b247c387763e8a9fcb3393f4da50023", "body_sha256": "2fb02450bbb86dfe1cf4c679f906fa53b58da08f46b72fe85cd260bca0215cc2", "previous_prompt_sha256": "d02c59c8f84024de6116e50f4b98af13aa435795a9ba2725a8a38bc82379936b", "word_limit": 61}, {"stimulus_id": "P008", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI 40f and my husband 42m have two wonderful kids 10m and 7f. \n\nOur kids have never been the best of friends or even got along that well most the time, they would bicker and argue with each other call each other names and do things they knew annoyed the other to purposefully get under their skin.\n\n I don't want to go in to detail but we've had some financial issues lately that caused a bit of a strain on our marriage, we would argue a lot late at night when the kids were in bed and often wouldn't go to bed ourselves until 2 or 3 :am ( even when we had work the next day). \n\nI'm ashamed to say that it turns out our kids would often wake up and hear our late night arguments and this actually gave our daughter nightmares, I found this out when I went to wake my son and saw his sister in bed with him, that's when he told me she had a nightmare and got in bed with him because my husband and were still up fighting. \n\nThis broke my heart to know we made our daughter scared and weren't  there to comfort her,  we made sure to keep our arguments as quiet as possible and reasured our daughter that sometimes mommy and daddy fight but she didn't need to worry about that and everything would be okay. \n\nWe kept our arguments to a minimum and were as quiet as possible, but our daughter still had nightmares the next few nights and got in bed with her brother. \n\nWe were able to get a handle on our financial issues and stop fighting so much. We reassured the kids that  everything would be okay and that they didn't have to worry. After a few nights our daughter was back to sleeping in her owne bed. \n\nEver since then our kids have gotten much closer, they play together, watch shows together, goof around together, and treat each other with much more love and respect then they used to. They even hug each other goodnight every night. \n\nThey still have arguments and bicker but it's much less and they  have an overall very loving relationship. \n\nToday my daughter drew her brother a picture of the two of them playing in our yard with the words \" best big brother in the world\" written really big on top. \n\nMy son loved it and showed it to us and asked if we could have it framed, as I mentioned we have been having financial issues lately and I really don't think we could afford to frame it. \n\nI told him he didn't need to frame it, he could just hang it up on the wall. But he said he wanted to frame it because special pictures get framed and this is the most special picture he has. I tried to tell him gently that we can't afford to frame it but he and his sister are still upset. \n\n\nI asked my husband about it and he said maybe we should get it framed because it's so special to our son and there new found closeness could maybe be hurt by us refusing to frame it. \n\nThe last thing I want to do is hurt there new close relationship but I still don't think we can afford to get it framed. \n\nAITA?\n\n", "prompt_sha256": "7b5ec9f8cbb11ad73211dd85bb3dbe1973136c6ffe3314cbcd1872c9b1d0826d", "body_sha256": "4b9be5a52b2922098ee42f69cf2aa8441c818c784c0c47d046c57fd6afaef3de", "previous_prompt_sha256": "548a165a69f8eb5b7488409f5a8caf3141fd4950002ea29368167fa51366958b", "word_limit": 61}, {"stimulus_id": "P009", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI'm (17M) required to eat breakfast at 10:30am sharp and to finish by 11:00am (Lunch and Dinner also have their respective eating times but it was specifically a \"violation\" of the breakfast time schedule that caused me to write this). It's not the amount of time that's absurd, but rather the fact that I can't eat whenever the hell I want to eat in my home. Usually when it comes to food I just eat whenever I want to because I'm personally someone who doesn't mind being hungry for awhile and only eat when I REALLY need to. Additionally I hate eating breakfast, I've just always hated eating in the morning cause I never really have an appetite so early in the morning. I understand the old \"My house, My rules\" bullshit argument, but I'm 17 years old and I think its stupid that my parents have authority over my eating habits. I understand that my parents would be worried if I didn't eat at all since I'm a relatively skinny guy, but I always eat the food she \"gives\" (more like forces) me to eat, just at a much later time. Anyways the situation where the \"AITA\" question can apply to is today when I woke up pretty late \\~10:40 and just decided not to eat the yogurt my mom told me to eat, and when she called at around 11:40 she yelled at me for like an hour for not eating some fucking yogurt. I understand that I didn't keep our \"promise\", but in my opinion I think its stupid to get that angry over some fucking yogurt.", "prompt_sha256": "d8c8d6d07a50f801275dc946940f3aa74e66c437adaaf367dad0690ff08aec3a", "body_sha256": "3b815f87a171b5c67136ace974f03247b26b8c11570493b63c242e3ef7ba81be", "previous_prompt_sha256": "2ced7d70ac42de4fbe8eac837475da103cd852b1771556cc79808317f0e422f7", "word_limit": 61}, {"stimulus_id": "P010", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nHey I’m new to reddit and typing this on my phone so I’m not sure how the formatting is going to turn out sorry I’m advance.\n\nNow for the story I’m a 16 yo male who’s parents are divorced and I live with both 50/50 split. Anyways I keep a dream journal so that I can help remember my dreams. This dream journal is just an app on my phone with a password lock. My mom has always gone through my phone and such but I never had a problem with this as I either don’t have anything to hide or I am easily able to hide it as she isn’t very techy.\n\nHowever one day she went through my phone and tried opening my dream journal and almost blew up when see saw that it asked her for a password. See said i was sneaking around and trying to undermine her. When I told her it was a dream journal she finally calmed down a bit asked me to open it up to which I said no. I feel that what goes on during my dreams, especially because I am not always in control of what happens, that I have the right to keep that to myself.\n\nMy mom however disagreed and took my phone and went to my girl friends house to try and get my phones password from her. She wouldn’t budge (huge shoutout to my gf). However her parents who I respect and have always kinda looked up to told me that I was being very mischievous because I wouldn’t unlock the journal.\n\nWhen I went to my dads the next day I asked him about it and he told me that I should just let her see it which is what really made me start to think that I may be the unreasonable one. This is because if there was something my mom was doing wrong he would jump at the opportunity to shit talk her.\n\nWhen I came back to my moms house a few days later she acted normal and gave me my phone back which was very surprising for her. Then again later in the week when I thought that it was all over and I don’t have to think about it any more my mom marches in my room grabs my phone out of my hands goes to my journal and unlocks it. I still have no idea how she got my password the only thing I can think of is one of my brothers ratted me out. In the heat of the moment my brain thought that the only way to stop her from seeing everything would be to grab the phone and delete the app as fast as possible. This was actually most likely true as I have no idea how to change the password on it and my brothers would have probably taken my phone before I could do it. I did this fairly easily and before she could call my brothers to help her stop me. \n\nShe was obviously pissed about me deleting the app and grounded me and all that. However the thing that was the worst was when she posted on Facebook about what I had done all of the people commenting were siding with her. \n\nThat journal really did mean a lot to me and I feel like what I did was spiteful as I doubt anything would have come from her looking at it. I just need some people to tell me what they think good or bad.\n\nUpdate: \n\nMy attempts to regain my journal have been fruitless however I did email the devs to see if they maybe kept data for x amount of days. Still waiting to hear back.\n\nFor the people asking about anything that might have warranted my mom wanting to invade my privacy she thought she caught me do drugs once but I passed 4 tests and get tested regularly for sports. I have had “incidents” that look like I was trying to harm myself and I believe she may have interpreted them that way I have made every effort to show her that she is wrong.\n\nUpdate: 2 \n\nHoly shit this post blew the fuck yo thank you to everyone for your feedback I had read every comment until a couple hours ago. I just woke up from about 2 hours of sleep and in that time I gained over 1k comments and 10k upvotes. Thank You. I will be reading them all replying to all the ones I can however due to the insane amount it will probably take days to read them. Thank you again and thanks for all the support.\n\nUpdate: 3 \n\nUnfortunately the devs were not able to help me recover my journal\n\nHowever my mom did see 500+ notifications from reddit. Tho I wouldn’t let her look at them and told her that she won’t be allowed to access my phone for a while. She was not happy about it but once I reminded her that no she wasn’t the one who payed for the phone she seem to calm down (I was the one who purchased it and I pay my own phone bill every month). I don’t know if she feels bad about what happened and wants to give me some privacy or what but if she is leaving me alone I’m happy.", "prompt_sha256": "de6cab47d57873fc300b076c17915d95a26ff6a933c6f2c70db80dadf67c8ef6", "body_sha256": "ecb1731aea767abde6aed625368f7825ab8f8bd41928431b8c2a68b41539073d", "previous_prompt_sha256": "4fe4dfcc64e3c774a9c7d9c40b2450b04cc094f3538206b0e56e7599843177c8", "word_limit": 61}, {"stimulus_id": "P011", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nBackground: my husband and I split after his current g/f found him cheating with another g/f and a friend suggested she call his “ex” wife…(me) needless to say the marriage ended. Since then my ex has had very little to do with our kids, hasn’t seen them in 3 years and sometimes calls them on their birthday. He had another child with his current partner but hasn’t even told our kids about it. \n\nLast week I received a text from my ExMIL who I have had little to minimal contact with in around 4 yrs stating that their grandfather is Ill and won’t be around much longer and could they have a photo of the kids.\n\nI’m have not yet responded because of the following:\nMy ex almost bankrupt me and my parents (guarantors on the family home) because he decided to live in it but not pay the mortgage or council rates\n\nMy parents were always the ones to help us out if we got in a bind whilst his parents just sat back and did nothing\n\nMy ex walked out and has shown no interest in the kids (forgot his daughters bday)and never rings them (I’m talking will ring max 3 times a year bdays if he remembers and Xmas)\n\n My ex in-laws were of no assistance when the bank was looking to reposes our home and take my parents home to cover the cost. \n\nI have sorted that all out as my ex husband just kept changing phone numbers and wouldn’t provide any address (again ex in-laws didn’t help) so it all fell to me to make sure my parents didn’t suffer any consequences and is now all sorted. \n\n\nI now feel like this request is just a way of self gratification of “look at our family/ grandchildren” when they have no idea of what family really means. \n\nSo AITA for ignoring a request of photos???\n\nETA: I am happy about the split, it gave me the reason I needed to leave him…", "prompt_sha256": "1dd28eb71fb31351d5e83978c54aec9fa0da2d69dcb15772d6d2fcfbaacbcf70", "body_sha256": "31913b882965295aaa89becce846464b3b4124f61920bf7fcc6623339466871f", "previous_prompt_sha256": "29c342b926c8eb3c562f1b7ee5b3d2d6301ed598e7fe28d7d3df107a5a9f4cb7", "word_limit": 61}, {"stimulus_id": "P012", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nGF left for work this morning wearing a pair of incredibly see through leggings and a black thong. Mentioned it to her before she left and she claimed both that it was all she had left to wear and that they were comfortable, but we had done a ton of laundry a couple days ago. I get that leggings are kinda see through but i feel like shouldnt be able to tell exactly what kind of thong shes wearing. I accused her of wanting to show off her goods (in my mind thin leggings and thong is a go to for people trying to do so) and now we are fighting over it. Keep in mind that I really do trust her but little things like this have started to rub me the wrong way. AITA?", "prompt_sha256": "da394622936c76ae8193e2c8d764c53d4d71bbec621ae34e3e2dd03cf0439090", "body_sha256": "cff9214650c2113dbdd3f65d111832c88df0d8b99bb4e4baf4bd5a4a0c1315b3", "previous_prompt_sha256": "ac1e1d9cc0cf06b8b1b8ac9d90e51b313e2410acd7c7c9b3fc250dde55f8dd55", "word_limit": 61}, {"stimulus_id": "P013", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nSo my daughter Jayne has been struggling with her mental health for a while now, and the ongoing global situations flipping her life upside down have not really been helping. She has had a lot of trouble accepting her illnesses, and still does today. When we first started noticing changes in her behavior, she would snap and claim she's fine, or just tired or stressed out from school. It was an uphill battle convincing her to go to therapy. I tried to make it easier for her by giving her a little more control over what's happening, such as letting her try out few different therapists, and choose the one she likes best. Jayne's answer was \"no therapist\". At that point, I got frustrated and basically told her she didn't have a choice anymore; she needs to go get help. It was getting to the point I was worried her school would ban her from campus. \n\nDue to certain recent events, her mental healthcare team has strongly recommended putting her in a mental hospital for a few weeks. My husband/her father and I have talked this through, and it's honestly the best decision. We're very worried about Jayne. Nothing else we've tried so far has worked or helped much. Unfortunately, this also means she will have to spend quite a bit of her Christmas holidays in the mental hospital. \n\nJayne was absolutely LIVID when we told her. She loves Christmas; it's her favorite holiday and to her, \"the most wonderful time of the year\". She claimed we were ruining the only thing she looked forward to all semester, she wanted to bake cookies with her grandparents and spend the holidays at their house, put up the tree now that school/midterms have ended, see lights, go to parades and shopping, eat her grandpa's special christmas dinner, basically do all the traditions she used to do. She lashed out and screamed in our faces about why we couldn't wait until after christmas to send her, we were ruining her holiday and making her feel even worse than we already do bc all we do is give her crap about her brain and are brainwashed stupid for thinking anything was wrong with her and projecting it. \n\nShe's extremely close with her grandparents and they love her to pieces. Before her grandma got sick earlier this year, she, grandpa, and Jayne would decorate their house to the nines. Her grandma's illness has been extremely hard on Jayne. She wants to spend as much time with them as she can. Her grandpa has said he would be more than happy to have someone dismantle all the decorations and tree so when Jayne gets released, she can come straight to their house and they'd help her, the best they can, redecorate the place, and he would cook her his special dinner and try to do as much Christmas as they can just for her. Not enough. Jayne said it won't be the same, bc she would only get 2 or 3 days before school started. \n\nI feel terrible. like i'm failing my child. i'm doubting myself. i need to know if im being an asshole", "prompt_sha256": "5daf9abfa59bdd04f1761bb17b5f36318026f7b14dc7a9e0d7c4645dc4c84fba", "body_sha256": "ba477e9456a67aa8230d10de4b633c5200757294949dd1633427a154e3c647b3", "previous_prompt_sha256": "22a175dc22a83cd21654d2de638e6e3484a48e6fa393896f3daeecae36d50723", "word_limit": 61}, {"stimulus_id": "P014", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (35f) I lost my father very early when I was 5 years old. A few months after his death, my mother married a guy named \"John\". John already had two teenage boys and he didn't want to raise me because he never wanted to be a girl's father. My mother, like a good mother, abandoned me with my aunt and took my brother (8 by the time) with her to live with her husband. John was a man with a lot of money and he always spoiled my mother and brother, but he never bothered to get me even a Christmas present. My mother didn't do anything for me either, she came to visit me once a month and didn't even call me at Christmas or New Year (I always called, but many times she didn't answer). My aunt was a woman who couldn't have children, because of that she and my uncle raised me as if I were their daughter, not missing anything for me. \n\nEven without much money I accumulated some money from my job I had during high school and I earned a small amount from my aunt which was enough for me to pay for my college. At the time I graduated in computer science and went to work in a good company earning a great salary, but eight years ago I received a much better job offer in a large company (One well known for having great Hardware products). In that time, I accumulated a lot of money and helped my uncle and aunt renovate their house and I always sent them a nice amount even if they told me to spend it on myself. \n\nI currently live alone in a great apartment with an estimated value in the millions. Recently my mom called me on my Instagram (I post a lot of pictures of trips and fancy places I go, it's not too hard to find me). She asked if we could meet to talk and reevaluate our relationship to forget the past and move forward as mother and daughter. I have a soft heart so I took it, I thought it would be an opportunity for us to talk and finally create the bond I always wanted. We made an appointment at a restaurant downtown and met there. \n\nWhen we got there she hugged me, kissed me on the cheek and said she missed me. We talked about my life and when I asked how hers was going, she started to talk about how bad she was. Apparently she divorced John and my brother didn't want to keep her as she is now poor. To make matters worse, she lives on a pension from John and has serious heart problems. After a while she asked if I could pay for a surgery she needed. The surgery was quite expensive, quite a lot. I told her I wouldn't pay as I wouldn't feel good doing that. She yelled at me in the middle of the restaurant, said I was a terrible daughter and that I was letting her die even though I could pay for her surgery. I left there very embarrassed.\n\n\nWhen I told my aunt, she said it was my decision but remarked that I have plenty of money to pay and that it wouldn't affect me financially. I don't want to do this cause she never have been a mom to me, but i need to ask. AITA?\n\nEdit: English is not my 1° lenguage so maybe i have mispoked something.", "prompt_sha256": "37a22528a177c071b20eb82a4bd57c0db7917c7122484879fc44f0e938d894c0", "body_sha256": "01d425c4f193833937ad5571e1620a8d7d147ffdc49b48691032fb7d62880db0", "previous_prompt_sha256": "b408218ae733446b375ca1337ff64405e06fdc71a1a74ca529c05be639dfb5dc", "word_limit": 61}, {"stimulus_id": "P015", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nWe lost our son Mason 5 years ago when he was 12 and our lives fell apart. I drank more, wouldn’t talk to anyone, eventually my ex and I got a divorce due to our many problems (my drinking being a main one). That was my rock bottom and I started trying to get better. My sweet Mason had a best friend he knew since kindergarten, “Ricky.” I lost contact with his family for a while but a couple years after my son passed Ricky started coming by the house almost everyday after school. I was still recovering from my alcoholism around that time so I feel it was to also keep me company.\n\nHe’s honestly a great kid. Very kind and so mature beyond his years. It helped a lot spending time with him, lord knows he was in pain too losing his best friend so young. We have gotten pretty close and consider him family.\nRicky is starting his senior year soon and going to be applying to colleges. I haven’t told him yet but I was putting money aside for years since before Mason was born in the hopes he’d use it for college. My parents gifted me the first check. It’s not a whole lot but it would be enough to cover several semesters depending on where he goes.\n\nRicky has no contact with his mom even though she technically is the one who had sole custody. He’s been living with his grandpa for years so he’s been worried about how he’ll apply for financial aid. Don’t want him to worry which is why I wanted to cover for it. As someone I consider family and someone who was my son’s best friend.\n\nThe problem is my ex knows I had this money saved. She got remarried 2 years ago and her stepdaughter will also be starting college. My ex and I get along and we still talk so I know she’s fallen on hard times. Both her and her husband. That’s why she’s asking if I could help her out here and it would mean a lot to them.\nI was deeply conflicted about this until I said no because I’d like Ricky to have this. But she’s still urging me to change my mind. And asking, as the mother of my child, to please help her family. \n\nLike I said we get along and I have no I’ll feelings towards her family. This isn’t about being petty (which is what she’s starting to call it), but I know Ricky will struggle too and I’d like to help him. We’ve had arguments over the phone about this and she still won’t drop it. Now she says she feels like I’ve let her down, didn’t think I’d be so unwilling to help them out after everything we have been through. \nI understand it’s my money at the end of the day, I’d just like to know if I’m not being an asshole with her about this considering she’s asking for help.", "prompt_sha256": "26b25258b4066bbc1fab64259f83ed3da4c141bacd05528b08829bcf3c93be74", "body_sha256": "63c1cbde465be9c102fbf89beaeebeb4eede25325f0f470db58aca962388c075", "previous_prompt_sha256": "a7df7ccb4bb7be5fc5ae328d34886900a421a63a68f025d2e10e9a0bb097f6ff", "word_limit": 61}, {"stimulus_id": "P016", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (17F) am turning 18 in July. Because of this, I'm already starting to prepare what I'm going to take with me when I move out, even though that likely won't be a while because I also plan to move in with 2 of my close friends and we need to arrange where we'll be living first.\n\nSome things I definitely want to take with me when I move out are my gaming consoles. An Xbox 360, an Xbox One S, and a Playstation 4, all of which were given to me as birthday or Christmas presents. Because they were given to me specifically, I think it's only fair that I get to take them with me when I move out. However my mother doesn't seem to think so.\n\nMy mother believes that I can only take one console with me, the ps4, and leave both Xbox consoles with them. Her justification for it is that she and my sister (5) \"won't have anything\" if I take all the consoles. She also said that it's a thing that when you get a new console the older one is \"passed down as a family console\". I thought this was completely stupid, because they were given to me as gifts, and now she just expects me to leave 2 of them behind just so they can actually have gaming consoles.\n\nI'd like to add that I've spent my own gift money on both the ps4 AND xbox one to buy games and other things for certain games, but she's also bought quite a bit of stuff on the xbox too (DLCs for the Sims 4 mainly). That's another reason why she doesn't want me to take the xbox one, because she spent money on it herself.\n\nI feel like she's trying to just guilt trip me, but I need to know if I'm really in the wrong for wanting to take things that were given to me with me when I move out. WIBTA?", "prompt_sha256": "bc173a005402db655f984e98783f83359f51787c9bd35ae6bb5a2d2b8828df68", "body_sha256": "697136ad18f06c75589ef683f4b7a83079380a53d69d728793e71bf07e150b5e", "previous_prompt_sha256": "e6c40d7337e51cb65e9496c1c2a4aadaa6bc21da27eb2aea9ba6efa1823ca97f", "word_limit": 61}, {"stimulus_id": "P017", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nSo for context: I'm a 22 year old male working at a warehouse and I got upset today with my 58 year old coworker because she expects me to lift all the heavy stuff because he ribs hurt. Am I being an a-hole or reasonable? Please let me know and be as honest as possible. I'm hearing everyone out.", "prompt_sha256": "38b8bdf106d3bce6d4167b0ad140ea95d144a8c844d91394990ba8b0ac21fd6c", "body_sha256": "ff80ed8da970c6e3fd8d0b44a654c6e3e8256998ac4c28af2c0c9488cb873c61", "previous_prompt_sha256": "c2c870772da1209e8bf9de71ae0104d1a4fe4dd30d9ee45bdff05f9518d21af0", "word_limit": 61}, {"stimulus_id": "P018", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (M21) have been in a long distance relationship with my girlfriend (F20) for three years now. Around the beginning stages of our relationship, she revealed to me that she is a type 1 diabetic and I told her that I still accept her for who she is.\n\nAt first, things didn’t seem that bad. She had only mentioned it to me once and that was that. I didn’t really see it negatively impacting our relationship because of the distance between us. About two months ago though, she has been bringing it up more and more, to the point where we cannot have a conversation without her mentioning her diabetes at least once.\n\nI've always been suspicious of her apparent diabetes diagnosis as she doesn't strike me as someone who is a diabetic. During our FaceTime calls I've seen her drink regular soda products which makes me suspicious because I don't think diabetic people can drink soda.\n\nThe other night all of this came to a head. We were on our usual FaceTime call when she went to the kitchen and I proceeded to watch her drink a bottle of coke. I don't know what happened but I just began to yell at her and accuse her of not being diabetic because what diabetic person drinks this much non diet soda? She scoffed at me and said ''she couldn't believe I would accuse her of lying about being diabetic'' and ended the call and now she hasn't responded to any of my texts or calls for almost 2 days now. So, AITA?", "prompt_sha256": "b3bba6aaa8e643032a56940f7408dd62bd16ac54c6ec8b9f974f3d3f2b2e1410", "body_sha256": "fdbb506347228741a151250519b8203029648b3d6571a079f682d2349eda8cd2", "previous_prompt_sha256": "6cb479ad97a1df321b51d382b7933adba98d6f1e75419058d6defbc1971587d6", "word_limit": 61}, {"stimulus_id": "P019", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nFor some background, my (45f) daughter (18f) applied to universities last year and was accepted to one overseas. She was excited when she got the acceptance letter and forwarded me the email to show that she was accepted. It was a big deal to her because it was in the field she wants to go into (cybersecurity) and it is one of the top universities there for their computer program. Due to covid and other fundings, she was not able to go but has been doing all she can so that she can go. She would leave this fall. \n\nFrom the beginning, I was wary of her leaving due to her being miles away with no form of contact. Since our Christian beliefs say to pray about big decisions, I told her she should do just that and see what God thinks she should do. A few days later she comes back and she believes she should go because she prayed about it. I doubted she did because I have seen her begin falling away from the church (that is another story) but I went along with it. \n\nIt is now a year later and she is a few months away from leaving. I keep asking he if she should really go because of the war overseas, her mental health not being the greatest, and if she has sufficient funds. She has told me that with her government financial aid, that she would be covered on the tuition, maybe even the housing aspect, but she is going to be taking the summer semester at the college she is currently attending to work full time at her job. \n\nI told her she should take a mental examination to make sure she is mentally prepared for such a big change and make sure that the meds she takes for her physical and mental problems will be with her and she would be able to get them overseas. I also continually advise her for only staying a short time because i would miss her since she wouldn’t be able to come home for the holidays. I tell her that i would miss her as my friend and my daughter and that I can’t handle her being away. \n\nShe has told me that I don’t need to worry about her and that she will be fine. Recently she told me that she is planning on staying there for 3 years. I begin to advice her against it because she could find a man in our religion and fall in love with him and never come home. She assures me that she will be fine but i keep pushing her against it. She started crying and saying that only her stepmom and friends are supportive of her decision and encouraging her and she wishes her dad, mom and other family would be supportive of her decision since she is an adult. \n\nAITA? my daughter has been barely speaking to me about her decision and will avoid talking about it at all costs. I just want her to be safe and make sure she isn’t going to fall away from our religion more than she already has. I am just concerned that if she leaves, I will never see her again.\n\nEDIT 1: Thank you all for your feedback. I saw a few comments with questions pertaining to the war and the no form of contact and thought I should clarify. \n\nThe no contact: It would be very hard to get in contact if something went wrong and international data plans would need to be in place for her and contact. The time differences would also be hard to work out times to talk with her. \n\nThe War: No, she would not be going to the Ukraine or Russia for her studies, it is just a fear that if the war were to spread farther, it would be very hard to not have her where i can protect her. I would also do all in my power to get her back home so I know she is safe.\n\nEDIT 2: Also, I would like to say since the post is getting a lot more traction than I thought (i was only expecting 1-10 comments at most) is that I am the daughter. This has been going on since I found out in December of 2020. My mom and dad have been pushing the situation with different things and even with my step mom they have all been pushing religion into it. My step mom however is on board as long as I can get religious ties there (which for all of my parents and extended families peace of mind I did but I have no intent of actually going). \n\nOne thing I should also say is that the part of sharing that I will be going over for 3 years is false. I have not shared that I would be staying for 3 years due to specifically my mom and dads reactions until i was over there and they were back at home and the could do nothing about it. my step mom knows that i am planning on staying longer, but she does not know how long. The reason is because I know they will all do their best to get me to not go in the first place so I don’t want to say anything. I also have not told them that  if a job opportunity comes up, i would apply for dual citizenship and live there rather than come home and take the internships I have been offered by family members in the field. \n\nI also want to add that while I am currently attending a different university while living at home, I am planning on transferring to the school overseas. I am also paying for my own schooling and so if my parents were paying, I could see them not wanting me to go (even though it will be the same price as me getting a bachelors over there as getting one at the current school i’m attending). I also have 43 credits already under my belt so 3 years is an oversight to be completely fair. I am taking the semester off at my current university to work and plan on getting off my parents phone line and getting international coverage on it since I don’t want my parents having any access to my phone. I would also be paying for the plane ticket there and if i wanted to come home, i would pay to go home.", "prompt_sha256": "020ce043ff537f73e8e96ea520a86f56a388eaccbd4bc39ba498a36a8992ab85", "body_sha256": "7ef84a210af710ccda0e7ca71afe87df0ff820da0dea550891bd8b82c2216b3a", "previous_prompt_sha256": "7c48e548cce7055bc216da1e3c1777de0dbd07ce88c099350ca855b450949854", "word_limit": 61}, {"stimulus_id": "P020", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (28f) and my wife \"Anna\" (28f) adopted a beautiful child (\"Molly\") when she was 1. My cousin \"Alex\" (15m) and her get along very well. He's very mature for his age so we pay him to babysit from time to time (we insisted on paying, he offered for free). \n\nAnyways, my cousin is very into music. His favorite is a band called The Descendents. They're punk rock.\n\nWell Alex was watching Molly one day while Anna and I were both at work (pre-pandemic). We typically have different work schedules but thankfully it was a day that Alex had off of school. We asked him to watch her and he agreed, then we payed him $100. \n\nAlex bought a new record player (this would be his second total) the weekend before with the money he's earned. He also has almost every Descendents record and CD.\n\nI think Alex wanted a chance to listen to his records and test his new record player. Him and Molly were sitting on the couch while listening to some of his records. Alex insists that he skipped over the inappropriate songs. Well Molly absolutely loved it.  \n\nAlex gave Molly his portable CD player and a pair of earbuds. He burned some Descendents songs to a few blank CDs for her. Idk if its important but a few of the songs on the CDs were: I Wont Let Me, Sick Of Me, She Loves Me, Without Love, ane Smile.\n\nWhen I came to pick up Molly, she was humming and listening to her CD player. I like to talk to Alex a little bit to make sure everything went fine and to just see how he's doing. He told me about Descendents and said, \"By the way, there are a few songs that aren't very appropriate. Some of them, especially from the early 80's, have some...outdated lyrics that the band doesn't believe in today. I gave her some of their fun and kinda cheesy love songs. I didn't know if you wanted her listening to that or not.\" He gave me a list of the songs with outdated lyrics, sexual lyrics, and swears so I would know not to let her listen to them (and to review them myself).\n\nI didnt think anything of it for a few months. They continued listening to Descendents when she was over, he actually got her into playing guitar. He teaches her Descendents songs and they play together. Then I looked up the lyrics to one of the songs on the list. I was appalled. It was the song Im Not a Loser. \n\nI confronted him about it. I freaked out on him. He said it was on the list and not her CDs for a reason. In a fit of rage I broke one of his records, his copy of Mellon Collie by Smashing Pumpkins or whatever.\n\nI banned Molly from listening to Descendents. I threw away her CDs. She's obviously not happy. Apparently the record I broke was valuable so Alex isnt happy and insisting that I buy him another copy, his parents agree. I looked it up on amazon and its over $200. I am not paying that because he exposed my daughter to inappropriate music!\n\nSo Reddit, AITA?\n\nEdit: We've been NC since", "prompt_sha256": "710842d3a6993936caed83960235853f1eab03c1255ae5463a514bce1687a20a", "body_sha256": "538e221bf981f73fd26a56d871358d7c30779295ced64079e5f63d62827cd5e4", "previous_prompt_sha256": "72317807ff2e1787ebcd26850ca9402650e110254b36ee933f2f23ec00c07d4b", "word_limit": 61}, {"stimulus_id": "P021", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy gf (F30) and I (M28) recently fell on hard times, and her mother has been very gracious to help us out (a place to stay, new phones, etc... with the promise that we would pay her back). \n\nI just got a great new job and am still waiting for my first paycheck, and have budgeted to pay her mom back, fix my car as well as get it registered and insured, pay the phone bill, save for a new apartment, all on top of daily needs.\n\nSince it's Friday the 13th, she wants to get a tattoo and the one shop near us that's doing them will be swamped and realistically won't get her in until 4pm, which is when I have to go to work. We only have 1 car (which still needs an oil change) until I get my car fixed and legal, so am I the asshole for telling her not to get a tattoo and suggesting that she should save what little money she has for the laundry list of things we need to get done and paid for?", "prompt_sha256": "179b587215e39e0f1e85201ebe06659ca800bce5dcbc41cba20809acc43d36d5", "body_sha256": "a38f3dc6dc9b51be6f83a36f403cc7599c99cff3e12e51e0e644121a44475476", "previous_prompt_sha256": "617ca978aaed2c48cde044fed2fd8e5691c3c22d08fe17a0d40d260a6d4bed6c", "word_limit": 61}, {"stimulus_id": "P022", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nSo this morning I sold my iPhone 8 I've been holding on to for like 4 years now for $100 to help pay towards the new 13 Pro Max 512GB. I've scraped together every penny I have as this is my dream phone and I am a photographer on instagram with over 900 followers so it is an investment in my career as a photographer.\n\nMy roommate hasn't been able to afford a new phone for the longest time in fact she has never even owned an iPhone because she is so poor. She is on an android which is just where you have to go when you are down in life, well I've been telling her I will give her my phone when I get a new one for years and she has been so excited for it but in the end my property is my property and if she wants to get an iPhone she should just get one herself", "prompt_sha256": "8108af8504f08aea1ffe1fcc3f59b693df8a14d8022f7ee632d84c7fcfcbca03", "body_sha256": "af3f99bd3822ad60ed5fb235d2a85c8007638a89d3abf266a4ac3b58ac8b571d", "previous_prompt_sha256": "5e46ccda9f45e1ff01ba8b8fffd1aca82d578a847c8db7d222a7cb1c65cbe269", "word_limit": 61}, {"stimulus_id": "P023", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (17F) have recently started seeing this guy (20M) who I'll call Ben. He is nice and charming, the life of the party, and we've been together for about six months now. A few days ago, he turned twenty, and he, his friends and I went to a sushi bar because he loves sushi. \n\nWe were sitting at the table, when Ben makes a joke about having sex with me in the restaurant (I'm a virgin, and I want to wait until marriage for sex. He knows this.) It made me uncomfortable, especially because other people where around, but I shrugged it off because sometimes my boyfriend makes inappropriate jokes.\n\nThe conversation continued, with me not talking much, when the sushi arrived. Him and his friends start talking about something, when I hear him make a joke about how his sushi looks like my tits. I'm embarrassed and his crude remark, and I quietly ask him to stop making jokes like that. Ben tells me it was \"just a joke\" and I need to calm down. I'm angry now, but he just gives me a kiss and tries to grab my breasts.\n\nI don't like much physical affection, especially in public, and even kisses make me slightly uncomfortable, but I know he really likes them. However, this was going too far for me, and so I get up and excuse myself to the bathroom.\n\nAs I do, he says something about my ass looking good. I turn around and tell him (not very loudly) to just stop talking about my tits and ass and how it is making me uncomfortable. Then I go outside and wait for him to come out, because even though it is my car we were driving in, I don't want to leave him stranded. A few minutes passes, and finally my boyfriend comes out, absolutely furious. He screams at me about how I \"embarrassed him in front of his friends\" and \"he can make whatever damn jokes he pleases.\" I tell him to just get into the car.\n\nWhen I get him to his house, he calls me an asshole and tells me to not talk to him. Looking back, I feel kind of guilty for embarrassing him, but at the same time, I don't think he should have kept making those jokes. AITA?", "prompt_sha256": "ec593cd03b5686ae598b02a37878bde19d2241850737f3aacf0f22881ecdaba4", "body_sha256": "15cff0f1870058f8f673c3783c04c57ae78bf5dabd93a1054576d3217e624f94", "previous_prompt_sha256": "234fc7a9357f0ff558e5b82eced0ec03fa1c664102a642384f6b3d9e2119e523", "word_limit": 61}, {"stimulus_id": "P024", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy (19m) Mom and Dad had me as a planned pregnancy, but they got a divorce right after I was born, and evidently my Mom slept with several men because about a year after they divorced she was pregnant and told her parents and my Dad she didn’t know who the father was.\n\nWhen my brother (17m) was born, my Mom listed my Dad as his father on the birth certificate and he just went with it and claimed my brother as his, even though it is totally impossible for my Dad to be the bio-dad.\n\nMy Mom finally told me about this when I was 13, and when I mentioned it to my maternal grandparents they flipped their shit and burst into tears and called my Dad who also burst into tears and he explained they never intended to tell me because they were worried I’d view my brother as inferior, which is total BS. I love my brother, I don’t give a rat’s ass if he’s got a different biological father than me, my Dad raised him too and therefore is his father. It doesn’t matter who provided the sperm. My Dad also told me I must never tell my brother because it would cause him to “go rogue” and “turn on the family in search of his biological father”. Also complete BS. But I agreed to not tell him because I don’t know what good it would do, and I didn’t want my weird ass family to throw another tantrum. But I also told my family that I will never lie to my brother if he ever asks just like I never lie to them when they ask me something. \n\nWell, 7 years passed and it was never brought up again, until about six months ago when my brother came into my room and just said “I’m adopted aren’t I?” He was under the impression that he was totally adopted and had no biological relation to me or any of my family.\n\nI froze. I didn’t want him to think that because I know that’s not the truth, so I said “No, of course not.” But then he said “If I’m not adopted how come I don’t look like anyone in our family like you do.” I had to tell him the truth. He’s 17. I couldn’t stomach lying to him. I’ve never been comfortable with lying about anything. So I just explained the situation to him and he seemed to get it and he just went back to normal. Then about three hours later my Dad calls me and starts screaming at me and telling me I’ve “destroyed everything”, and that my brother would never view the world the same again and that he was going to turn on us. I told my Dad that he was being 100% unreasonable and if he had just been honest about the situation from the get-go it wouldn’t matter.\n\nWhy is this such a big deal? My brother is 17, he’s almost an adult. He understands. He still views our Dad as his Dad. It. Not. A. Big. Deal. But my Dad and maternal grandparents have been guilt tripping me for weeks, meanwhile my Mom doesn’t care, and if anyone should care it would be her. I don’t understand. AITA?", "prompt_sha256": "4438fd8d5679d4a4c7a6ceaa7fe41765f87df480a36a8354230be42eed16c1bf", "body_sha256": "a245abef4ddb8f7a6c6c7651362637005509a5e153efbb5800c0ddbbf159aeeb", "previous_prompt_sha256": "a28fb68ea0621119a216f26d8ea8c332a846f57bcc4f85c74120366f53bcc806", "word_limit": 61}, {"stimulus_id": "P025", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy (19f) cousin (Jen-23f) works nights and so sleeps during most of the day, which is totally fair. The issue is with communicating with her. The rest of our family operates during the day, and so (obviously) all of our texting and phone calls take place at day time. We don’t call Jen but we do text her. None of us expect a reply straight away, but by her own admission, she wakes up at 5pm and leaves for work at 10pm so she has at least 5 hours to text back. I’m at the point where I don’t expect a text back the same day but recently it’s gotten ridiculous. \n\nShe sent a text to the family group chat ‘setting her boundaries’. It was 1 rule; do not text her during the day. Her ‘open hours’ are from 3am to 6am. Now, I get those are her awake hours, but she’s in the minority here. There’s 30 people in this group-chat and she’s the only one who operates at those hours. Of course, there will be some outliers, but I’m not staying awake until 3am to shoot her a quick text about if she wants red or green napkins. I’m all for setting and sticking to boundaries, but this is ridiculous. \n\nI sent her a text in November asking her what she wanted for Christmas and her birthday (early Jan) but she didn’t respond. So I didn’t get her anything. I was getting frustrated with Christmas gift fever and burnout and I felt like she was being deliberately irritating. She was leaving all my messages on read. Even ones where I said I can’t wait any longer to wait for her replies so now is her last chance before I skip her. \n\nI should note that I'm not texting her non-stop. I barely text her outside of Christmas and birthday shopping. I don't think it's rude or unreasonable to respond to a text about what you want as a gift in a reasonable time frame. Again, I'm not expecting same-day replies, but if you want something, you answer. I'm not a mind-reader.\n\nChristmas rolled around and everyone seemed to notice that I hadn’t gotten her anything. Jen seemed a little upset but she didn’t tell me, so how would I know? I tried talking to her later about her birthday, but again, she wouldn’t respond. So I did the same thing. \n\nFor her birthday, she simply sent me a link to an online shop, but no links to t-shirts she liked, or anything. I asked her what she wanted, and no response. I didn't get her anything. Her birthday was yesterday and apparently, she's been really upset. Her mum said I should have just gotten her what she asked for and ball-parked sizes. Here's the thing; she didn't send me the links to t-shirts, she sent me the links to whole websites with no indication of what t-shirts she wanted. I even text-searched to check in case I missed it. I asked her what t-shirt she wanted and she left me on read. \n\nI told my aunt this, but she said I need to understand and respect her 'boundaries'. I told her it's unreasonable to expect everyone to operate on her hours when her hours aren't the norm and that's she's being a hypocrite because she also complains about Jen not responding. \n\nAITA?", "prompt_sha256": "c5f62654f57e21424315a3a16e1636902fb78670f30f57b3d76af2a09793e1b6", "body_sha256": "7feba1de8dbf7f09a5346a748604e0f3938806fc8080da3d2cfc6ba875d267ba", "previous_prompt_sha256": "17960b9711e96ee1d16bfeb0948e18f5996f01ac3e1a418bad51c46133e87f6f", "word_limit": 61}, {"stimulus_id": "P026", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI(39m) have split custody of a 6 yo daughter, lately my daughters mother(31f) has been working part time and cant make ends meet. I have a full time job during the day and have my own LLC for just about anything under the sun. Past couple of weeks my daughters mother has been coming over and helping me out around with cleaning and other stuff while our daughter either helps her or plays in her sandbox. My friend Gia(24F) and her BF(28m) have been helping me with my LLC side and would be around my daughters mother\n\nWhen it starts to get late we give our daughter the option where she wants to sleep, either at my house or her mothers. She always wants to stay the night with me. So I tell her she needs to shower before she goes to bed(after she was playing in the sandbox or with the animals) Her mother told me she doesn't need to shower every day and wanted to fight about the subject. I know her mother hasn't had a shower in a few days. I told her every time she would come over to help I could smell her person \"hygiene\" and she might want to take care of that before telling me what is best. I shower every day (we both work in factories) so I know how much I sweat.\n\nGia told me I was being an asshole for telling her she needs to shower but her BF said it was gross and didn't want to say anything. SO Reddit, am I the Asshole for telling my daughters mother she needs to learn how to take care of herself before telling me how to take care of our child?", "prompt_sha256": "970fdb648517ddce67e7c8d6b05111d7439bd3b844bb403ea97b8e340edc9de8", "body_sha256": "b990d967daff837e3a69bee715d5ca15cdaf33fbcafc2a2639b8c6459ef10235", "previous_prompt_sha256": "294bf4ed18989dc5d4739b9f5aa91b49228d9c46a7759c0b4c25c6f5d0f28595", "word_limit": 61}, {"stimulus_id": "P027", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nHe’s been showing a failure to launch (I’m using this term in lack of a better one) the last few years with bad grades, horrible attitude, and no motivation for anything. He’s a teenager, I get it, but it got to the point where his room and our garage were absolute messes filled with his stuff and whenever we’d ask him to clean, he’d get mad and go to his mom’s house. He’d be rude to us and to his little brother (100% bio, not step) to the point where we all started dreading time with him. We tried giving him direction, advice, love, tough love, you name it over the last few years but it seemed nothing worked. So we told him when he was 18 and done with high school, we wanted him to chose his mom’s or our house to live permanently. We figured this would help to get him organized and focused. He chose his mom’s house which we figured he would because she has more space and no rules. My question is AITA for making him chose a house? We’re partly doing this for his own good but also for our sanity and the peace in our house. \n\nAnd to clarify, this is his dad’s idea and I am supporting his decision.\n\nEdit: he’s currently 18 and has graduated HS. We’ve offered counseling online and in person, tutors, supported his hobbies, given him chores and consequences for years. We figured the back and forth between his parents’ houses might be causing some of the issues so we thought it might be better for him to pick a house. Since he’s gone to his mom’s, we talk to him every day and invite him to dinner whenever we make plans. He’s welcome to stop by any time and knows that if things don’t work with his mom, he can come back here but there will be rules and expectations.", "prompt_sha256": "e138c0be63a3f770a4a1d3d8738bc95cb4549a9d3a55493f55be712acbd89c03", "body_sha256": "bec730a6f1ba0a8208425d1f918ba46668b912b10712855ae4d012892099b47e", "previous_prompt_sha256": "2d2231c767427ac712851ba0d62e5b50e1d136f5f80c60f45c47ad9f574e18eb", "word_limit": 61}, {"stimulus_id": "P028", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nSo I (23M) am dating Kelly (25F). Kelly has two very nice mothers, Gina (64F) and Stacy (71F), that I get on with quite well. The problem relevant to this post is that Stacy has a history of lying, very often, about things both serious and not serious, which Kelly has complained to me about a few times. While the lying does bother me, mainly because it hurts Kelly’s feelings and stresses her out, Kelly says she’s trying to let it go and has just come to accept it as part of her mother’s personality.\n\nWell, I went to run errands with Stacy last week, and when she forgot her wallet I thought it was a genuine mistake. She’s in her 70s, she’s forgetting things, it’s no big deal, I’ll buy her the couple things she needs and she’ll get it back to me when she can. It wasn’t until later that day when I was alone with Kelly and recounting my day that she stopped me as asked if Stacy had me pay for something. I said yes, and Kelly explained that this is something she does to everybody if they agree to go with her somewhere and she has/wants to buy something. She claims she “forgot” her wallet, asks you to pay, promises to pay you back, but almost never follows through. This was upsetting to hear, as I also don’t like to be lied to and had not experienced Stacy lying to me yet. It’s also not even about money for Stacy, as she has quite a bit to her name, no debt, and Gina pays most of the bills.\n\nAnyway, yesterday Stacy asked me to come with her again for errands, because she needed to pick up some things and they’re too heavy for her to handle. I agreed, and before we walked out the door I said “oh wait, I forgot something” and went and grabbed my jacket. I asked her if she was sure that she also had everything she needed, specifically listing wallet/keys/phone, she said yes. I asked if she checked before we stepped outside, she said yes again. So on we went, and after the initial errands we stopped at the drug store and she ended up asking me to grab her something while I was inside, claiming she forgot her wallet again. The conversation went like this:\n\nMe: I thought you said you had everything you needed before we left.\n\nHer: I did, I guess I was wrong.\n\nMe: You said you checked.\n\nHer: I did.\n\nMe: So did you lie to me about having your wallet or did you lie to me about checking for it?\n\nHer: I don’t know what you’re talking about.\n\nMe: Do you really not have it with you or are you lying about that too?\n\nHer: Why are you having an attitude with me?\n\nMe: Why did you lie to me?\n\nHer: It’s not a big deal. If you don’t want to help me then I’m going home.\n\nMe: I don’t have an attitude, I’m just not going to deal with you lying to me. Lying has consequences.\n\nShe was pissed to say the least and gave me the cold shoulder after this and Kelly says she hasn’t come out of her room since we got back from errands yesterday. Did I go overboard here?", "prompt_sha256": "e668bccc0cbb04a393c0366ba090158902f5e124ec6dfd39b0d08317827e6aa2", "body_sha256": "9caafc99ba36388a765191e0f2b0da0eef383e303b6e06055c27ba05db801bc5", "previous_prompt_sha256": "8b8d62db2cee0a03494fe2eab573457d1b1220cabedc3d648dc5c1cef1acf221", "word_limit": 61}, {"stimulus_id": "P029", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nOk so this is gonna be short but I'd like ur opinions cuz i really don't know if i messed up hard or not. \n\nWe were talking and she just randomly brought up that her friends brother hit on her multiple times and even texted her on social media and although she declined he kept doing it until she blocked him. I got bad tbh and told her to drop his addy so I'd have a chat with him about it. She said that she doesn't want me to do anything about it. I got mad and told her to give me the address. She said she doesn't wanna me to intervene but just wanted to confide in me. I told her that i respect her decision but she just shouldn't tell me than. \n\nAITA FOR THAT GUYS?", "prompt_sha256": "d6446873e17877cf196d96d200d7dae1ad21d7175d3a94830139298578bfc5b6", "body_sha256": "34dcc72dca9079adaca6f8da7036c504d0d4a6b1dfb2adea41a9373a0ee02611", "previous_prompt_sha256": "84c48b0d4d43a095749611bb4c31d9e7b279d004c22af44d55549a235d31be47", "word_limit": 61}, {"stimulus_id": "P030", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI am (16)M and my Mom has recently had 2 babies, After she divorced my Dad she met up with this new guy who is honestly a pretty decent guy. However 2 years into the relationship she told me that she was pregnant, being a freshman in high school it sounds horrific having a baby brother, I can’t have girls or friends over without being questioned and told how weird it is, I told her “Oh that’s great” and waited 9 months for this baby to be born, after he was born things weren’t awful, I mean it’s kinda nice having a little brother. Unfortunately a medical miracle happened and my mom somehow got pregnant again only 10 months after giving birth and I was mortified. The second little bundle of grief was born and life sucked, it immediately felt like all the attention was gone. I understand that babies are high maintenance but at least a conversation would have been appreciated. Throughout high school things just got worse and worse, the screaming, the shit, the destruction and it never failed to make me miserable. What has pissed me off most is the fact that now one of my little brothers is old enough to open my door to my room and I hate it, my room is the one place in my tiny house where I can just have peace and privacy and now that’s taken from me, so much stuff has been broken or almost broken because of them entering my room, and I constantly tell my mother that I don’t want them in my room but she just repeats the same annoying bullshit that “My room is a privilege and that I need to spend time with my brothers” but honestly I couldn’t give a shit about them. I don’t hate them nor resent them I just don’t care for them, I’m 16 and I have a ton of things I’d rather be doing and hanging out with babies that I have no care for is not one of them. What’s worse is how much my mother demands that I watch them and take care of their needs, these are not my kids and not my responsibility however I am constantly yelled at by her, my step father, and my biological father that I need to take care of them. Today was the final straw, I was just relaxing when they barged in,I told the, to get out but was met by a rotten scowl from my mother and she yelled at me to keep them in, immediately my switch was thrown of the floor, my desk was completely trashed, and my phone was being yanked out of my hands by my toddler brother, I was fed up and yelled at my mom to just leave because I don’t have any desire to spend time with them and to stop forcing me to love them. She gave me another scowl and told me that I no longer get my allowance or my console because I’m being cruel and heartless. So tell me, Am I the Asshole?", "prompt_sha256": "20716570bbd3f2e14640528fc6b28cf97967ae8c8960367e97e6ae4e48a50503", "body_sha256": "7a9f2d2937d80eb2e673f716a141f09c45a6f77c9c16532f0e1eb9944c2146af", "previous_prompt_sha256": "c65f058f120f5c9df424348c725b1ba1348e0ce6fbe5568a873ce9819128b40a", "word_limit": 61}, {"stimulus_id": "P031", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (27F) bought my first house two years ago. It’s a relatively small house (1,200 sq ft.) but I’m really proud of it because I bought it all on my own. So around a month ago, my friend since childhood moved into my guest room. She (26F) just got out of a bad relationship and she is new to my city. I told her she could stay with me (free of charge) temporarily while she settles and finds an apartment. \n\nSo today, she brought a standing mirror into the guest room. No concerns on my end, until I noticed she moved the chair that was in the guest room into my office. She asked me about moving the chair into the office before doing so, and I explicitly told her no. My office is tiny as is (and even more so now that I’ve moved things around to accommodate her). I work from home so having a functioning office is critical; with the chair, there is hardly room to walk around freely. \n\nI just talked to her and said that the chair cannot stay in the office. She suggested moving it into the living room, but again, no space and it clashes with the existing decor. She then suggested the basement. I live in a 100+ year old house and have a dehumidifier down there, but it is very common for my basement to have some water in it after a heavy rain. The chair has wood legs and costs $300, so I don’t want to risk standing water ruining the legs. I tried to compromise and told her that if she wraps it up appropriately and can ensure it won’t get water damage, I guess she can move it down there temporarily. But she got very upset and said that I was being unfair and trying to micromanage how she uses her room. I corrected her and said it’s my room. I said I was trying to be as accommodating as possible, but it’s ultimately my house and she cannot move things into my space without asking. She also said she’s already cramped enough as is, and I told her I lived out of the guest room for the first few months I owned this place before I could afford to furnish my primary bedroom just fine. I feel like I’m already doing so much for her, and I’m not being ridiculous by asking her to please not move my stuff.\n\nShe started crying and now is refusing to talk to me, despite me begging her to please talk about this with me. I’m trying to be a good friend, but I feel like this is my space and she isn’t respecting me. She also just lost a relative around a week ago, so I feel guilty now about upsetting her. AITA?\n\nEDIT: I told her she should move to my city after her breakup and she could stay with me until she found an apartment. She IS paying half of the utilities (electric, water, and Wi-Fi) while she is here, which is usually no more than $300 total per month. But she is paying nothing in rent.", "prompt_sha256": "67bebc5dc533a0f309dfb09729d64687a783e87861a2e3ea6b66e2885072eac3", "body_sha256": "23d52e84191186665751990bf356bc53d69d54136f4e5f506c0fe3751a2b65ba", "previous_prompt_sha256": "9fb1f7c5271182fed9bfee93cbfac7cbe1968986f17aea95cfa104dd68af01d2", "word_limit": 61}, {"stimulus_id": "P032", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\n* This was said to me. \n\nHello, fellow Reddit people. Hear me out on this, because I don’t believe I am using my autism, but some of my friends seem to think so, therefore, I’m in the public court of Reddit.\n\nI’m autistic and in a difficult university. I tend to avoid using accommodations, because for the most part, I feel that I can do fine without them. However, I have issues with processing videos and documentaries. Up to this point, I’ve never had a mandatory documentary to watch, so I’ve managed to avoid them. Well, a week ago, there was a review I had to write on a documentary, and I emailed my professor, telling her that I was autistic, couldn’t process, and if she needed confirmation from the accommodation services, I’d provide it.\n\nShe basically said to do it on the book the documentary is based on. I had two weeks to provide proof from accommodation services, otherwise she’d shift my grade to a 0, and that for future documentaries (we have two left), do it on the transcriptions; and she’d change the rubric accordingly.\n\nGreat. Super happy with her response, accommodation service are emailing her this week. \n\nI mentioned it to a friend about how much I appreciated her response, and he told me that what I was doing was actually cheating, since I was getting a different rubric than everyone else, and he called me an asshole, and that he didn’t take me for a cheater. Two others of my friends agree, because my assignments now require less work, and they said I’m just using my autism for an easier A, and that I’m just appropriating HOH accommodations. \n\nI don’t feel like an asshole but I also see where they’re coming from. So, Reddit please let me know. Am I an asshole?\n\ntl;dr i got accommodations because i’m autistic and can’t process documentaries well that  involved a rubric change and my friends are calling me an asshole bc it’s cheating", "prompt_sha256": "4d1e28d1c13a6976e3c6abc60b3a0c9cc22f42b92d3c080fe75d75b8d07d9695", "body_sha256": "7c031b43288d186013051bd44d629ed35f0d535360a82fc673384f7b78decb0c", "previous_prompt_sha256": "5f99332c3a584cf771d331b937a91e4e945f3e1530d976afd5dee4ddd5a579fa", "word_limit": 61}, {"stimulus_id": "P033", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nAbout two weeks ago, me and my fiancé held a  BBQ with both of our families. During the BBQ my stepbrother spent a lot of time talking to my future FIL about his latest business idea. My FIL is a successful entrepreneur and currently owns several very profitable businesses, so I assumed he was trying to get some business advice from him. It turns out my stepbrother asked my FIL to invest a substantial amount into this idea and my FIL said he would consider it. \n\nA few days later I was at my mom’s for lunch and my stepbrother (he lives with our parents) was bragging about how my FIL was going to invest in the business. My stepdad and SIL were super excited and kept talking about this was finally going to be the thing that “made” them. This isn’t the first investment my stepbrother has tried to get from my future family, a few years ago (when he was still my boyfriend) he tried to convince my fiancé to invest in a separate idea. It ended up falling through because my stepbrother lost interest in the idea. \n\nPersonally, I don’t want my family to mix business with my in-laws because I feel like when things get messy it’s going to be me who has to deal with the fall out. It also puts unnecessary pressure on my relationship which I’d prefer to avoid.\n\nThe next day, my FIL invited us (me and my fiancé) over to discuss wedding plans. Whilst we were there my stepbrother’s business idea was brought up. My FIL asked me some questions about his work ethic, his previous business experience and if I was comfortable with him investing. I answered honestly. My stepbrother did not have a very good work ethic (he dropped out of uni because it was too much work and left several jobs for the same reason), he previously opened a business with his best friend and it failed due to their laziness and that I would feel uneasy if he invested (but it was entirely his decision and he shouldn’t not invest because of me). I did mention that he had some good ideas but lacked the drive to fulfil them so maybe with my FIL’s help he could achieve his potential.  \n\nWell, my FIL decided not to invest. My stepbrother, stepdad and SIL have been blowing my phone up with texts and calls calling me a b\\*tch for lying (I didn’t) and that I always wanted to be the one on top and that I ruined their life. My SIL was crying over the phone and told me how I’d ruined their chance of getting their own places (turns out some of the money my FIL was going to invest was going towards getting their own place) and how they’d never have kids because of me (my parent’s have said they won’t support them if they decide to have kids whilst under their roof). My mom has stayed out of it.\n\nI do feel bad because I know how much my SIL wants to have children, but I have a really good relationship with my in-laws right now and if the business didn’t work out, it could ruin that. \n\nWas I TA?", "prompt_sha256": "504a2719de574b2c73eea43fb342c8e1a3d3df0247ea3d869051f504b56f2304", "body_sha256": "c6bc12ddf133c42fb64dfccb999b71499a6b6633ad69550bbf5985454401f1ec", "previous_prompt_sha256": "e4e4e598b9ca03ab150cde69e77aa46c6d4e99b6a088c272049a8e39b3ad3c3f", "word_limit": 61}, {"stimulus_id": "P034", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy (28F) girlfriend moved herself into my (28M) apartment about a year into our relationship 6 months ago. No formal agreement was ever made, and I went along with it as she was a flight attendant and not around much anyways (less than 40% of the time)..\n\n&amp;#x200B;\n\nI live in a country with insane housing/land prices, and thus only rent a small \\~500sqft apartment about 2hrs from the airport, whereas her family (where she lived prior to moving in) is about 30minutes away. While I've never had a dog, I was raised on a farm and have had cats, horses, chickens and generally love animals. Her family has a big \\~2year old 80-100lbs golden retriever, who I get along with perfectly, but would just be too big for my small apartment.\n\n&amp;#x200B;\n\nOne day she says she wants to live and move her (family's) dog to my apartment, and given her work schedule, it would mean I would be responsible for the heavy majority of the caring of the dog. I have a standard 9-6 job (with occasional OT, and a total of 2hr commute), which would just in my opinion make it not only unfair for me, but also the dog to be taken away from her family and full time attention from the rest of the girlfriend's (perhaps now ex's) family. And we end up having a massive argument where she essentially gives me the ultimatum of her and her dog, or no relationship, but leaves without my answer.\n\n&amp;#x200B;\n\nTo be honest, I already have issues over her heavy partying, drinking, and other small selfish problems here and there..\n\n&amp;#x200B;\n\nAs a pet/animal lover, I never want to be the one who makes a person choose between their pet and me, but given the circumstances, I just don't see how it'd be a good or feasible idea for anyone or the dog. AITA?", "prompt_sha256": "dae9c845413f301b578074703eddba7d22219bbbc171f931df87c15cac2b3703", "body_sha256": "5ef192d54e768f54a98dd3ad020ebbe7b76b94d574570c61d5d464fda60ca586", "previous_prompt_sha256": "de26a29def212aac1478ea9c23c9773ce56069d1daec0d4d3dd9c44543865758", "word_limit": 61}, {"stimulus_id": "P035", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI absolutely love Reeces cups. They're delicious and the pinnacle of candy. My fiancee also loves them, but sometimes she can't control herself. One day, she managed to eat close to 20 cups! 20, freaking cups. That was my entire stash!\n\n \n\nSo, I just decided that whenever I buy them 2/3rds will go to both of us and I secretly store 1 of them. I've amassed close to 30 cups and because I have an excess amount of cups, I've stopped adding to my stash. \n\n \n\nToday, she found about my stash and demanded to eat most of them because I've been squirreling Reeces cups for months now. I mean, I let her do it because that wasn't my entire stash( who keeps their entire stash in one place?). Anyway she got super mad at me for not sharing them. I mean, I know what she'll do whenever I share them; she'll just eat a bunch of them at once. \n\n \n\nSo, AITA?", "prompt_sha256": "424f953c5972b5dcb3195bb4b3da17ca89826811be8caa7fc448e220d6601282", "body_sha256": "ee89365c02b3668fc79c2cf367a8a9e8a84046e5bb434bffdfc82c1f8ee54a51", "previous_prompt_sha256": "f0bed9cec45cde926654efd04fbea4fe204f5d02c76822fcf74b0e398862c7d5", "word_limit": 61}, {"stimulus_id": "P036", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI (f27) found my mom and stepdad (f53, m41) on OF through a friend (m27) of mine. I have an OF myself and so does my sister (f30), so I'm not trying to sound like a hypocrite, but my parents having one and not telling us about it bothers me really badly.\n\nI won't lie though, my curiosity got the best of me and I wanted to see what they were posting on there, so I went incognito and paid for access to see their content. On their OF page, they post a bunch of MILF and younger guy-type stuff. The most disturbing thing I saw was a pic of my mom topless and wearing a pair of my old underwear.\n\nAfter seeing what I saw, I called my stepdad and cursed him out. I was mainly pissed that my mother was posting NSFW content in underwear that I wore probably when I was around 17-18, but I was also pissed that they kept their OF account from me. Anyways, my stepdad told me to shut the fuck up and mind my own business, and he hung up on me. I'm still pissed at them, but I think I overreacted a little too much.\n\nAITA?", "prompt_sha256": "896afd03e01f3b7fbc4086fe53087f70e893c8cdc3c66f284b19efe0a99ef10c", "body_sha256": "60aa3479cb7082ae2ad33dce42bfaba5722d03f0732cff726551b395f3dd7e0e", "previous_prompt_sha256": "d2ec7f711b80b001bf17c8307441597511291048e41530b10580c9b2d887d445", "word_limit": 61}, {"stimulus_id": "P037", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\ni (17f) moved out of home at 16 to a different state. long story short, after a few months my living situation went south very fast resulting in me coming back home. i moved purely for myself as i feel i have outgrown my family and need some independence, not because of abuse or bad circumstances.\n\ni’ve been home for about a month and due to my move i am now unable to complete my year 12 study, and have dropped out to work full time. i recently got accepted into the university of the city i had moved to previously, and planned to attend and live in student accomodation. this was ideal for me as finding accomodation as a minor outside of home is almost impossible. \n\nmy parents are not fond of this idea at all and think it’s best for be to stay home and work. they believe i will not be able to cope on my own, despite being able to do it just fine before. to prevent me going to uni my parents have made a promise they will find a rental to move to in the same city so i can redo year 12 next year instead of go to uni. \n\nhonestly, it would help me a lot to save money on living expenses for the next few years if my parents did move. however both parents are unemployed and out family income is below the poverty line which will make it very hard to move.\n\nthey have asked if i would be able to “help” out financially for the first few months until they find a job. ei. lend them the $10,000 i have been saving towards my future. \n\ni refuse to give them that amount, especially considering i am most likely not going to get it back. i argue why they would move to a new city purely to stop me from leaving home when they can’t even afford it themselves. i would save a lot more money by just moving out myself rather than supporting my whole family to move with me. \n\nwhat especially annoys me is that my twin brother (17m) is not expected to contribute a single bit, because he has never worked a day in his life and has no money to his name. i’m being called selfish for “not wanting what’s best for the family” and being made into the bad guy for just wanting to leave home. \n\ni don’t feel like this financial burden should fall onto me because i am the only one in the household who has a job (both of my parents have been unemployed for 10 years) \n\nso, AITA?", "prompt_sha256": "3271c45356eb0d130912e2ded13d163286e4ad94cb4b138a466800951aa5ab96", "body_sha256": "849cfee605ba940b10dab8a62176b017ed9edba4115eaecd8e7aec8a8d6acd22", "previous_prompt_sha256": "01e77c0b92e5f32cb5255c469d6abdea04762c6b42cd42b15aab421c81ff8ef8", "word_limit": 61}, {"stimulus_id": "P038", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nPosting on a throwaway\n\nSo basically I've been friends with 'Harry' for 7 years. We're both 22. We both went to a neighbouring city (about 90 mins drive) for our other mutual friend 'Lewis' 21st birthday. He goes to university in this city. Because lewis had many people for his 21st birthday night out he couldn't accommodate us so me Harry and another friend shared a hotel room. I paid the whole cost upfront with the agreement that both Harry and my ther friend would pay me their share back the next day. \n\nThe night out was great we all had a good time with no issues. The next day I was driving me Harry and our other friend back. Once we stopped I asked them both for the money. My other friend paid me straight away. But instead Harry said that he didn't have the money but instead he gave me this sports cap and he said it was worth almost the full cost of his share. He also said he'd paid for me to have breakfast at the hotel earlier. I didn't want any breakfast nor did he ever ask me if I wanted it. He told me to come downstairs for breakfast and I said I didn't want any so he just went downstairs and came back half an hour later. I didn't even realise he'd paid for me to have breakfast. So apparently his share was all paid.\n\nI flat out refused and said no because I wanted the money and not for him to just give me random things that I don't even want instead of the money. I didn't accept this and told him it was a joke and to pay Me as soon as possible. He was very upset and the next day on his snapchat story for everyone to see wrote 'me and my friend Darren yesterday we was bestfriends we have been for years but now he's acting like a debt collector, he wants money for a hotel we stayed at in York. But that's why I bought him a cap and he didn't want it.' This caused another argument. AITA for not accepting the cap and breakfast? \n\nTL;DR me and my friend Harry stayed at a hotel for a night out in a neighbouring city. I paid the cost upfront but he was supposed to give me his share back. When I asked for the money he said he'd paid for my breakfast at the hotel and gave me some random sports cap, I didn't want either and told him to give me the money. He got upset and angry that I refused his method of payment. AITA?", "prompt_sha256": "e705bedb8677cd7209a6fe68ab8c8afcfb1a1d75161679930e823493e90714b2", "body_sha256": "706b7f3160efdd09bc106c0c758fbc23165dac5c7087ba13b55cde7434cb07a0", "previous_prompt_sha256": "50a736d1a01362e863d799f14efb82006023ce6fd620ca194560d48b80ce9c7f", "word_limit": 61}, {"stimulus_id": "P039", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\n16 F, with three older brothers, all in relationships with three woman; I adore two of the girls but my 30 year old brother, Tams gf,  30 year old Cleo is a bit too much for my liking -in mean terms, I think she’s a racist stuck up bitch-  \n\n\nSince getting with one and other 10 years ago, she has made it a mission to be a bitch towards the family, she’s talked trash about me since I was at least 10, made digs at my weight -was on the verge of a eating disorder about three years ago, she hasn’t let me hear the end of that- along with the fact that she’s an racist old woman while I,my self the complete opposite.  \n\n\nHere’s the story: we were talking about her parents who were killed in a crash about 5 years ago now, I met them a few times and  vowed never to again because you can see where Cleo gets her way of thinking from. She then started to get into a debate about people of different races and when I asked why she thought like that her words were: “oh my mom and dad just raised me that way, no bigger”  I couldn’t take this so I told her this: my grandpa was a former klansman and raised my dad with their way of thinking -He’s now fully out of the way of life, I’ve made him read a lot of books on racism and made him to talk to those he’s offended and now lives a very diverse life- never killed anyone but were definitely not nice people, mom was never racist with intent but could be very racially insensitive towards other races, while I have always just known that their way of thinking was wrong and I knew that I would never have that way of thinking, so I thought I should say this:\n\n\n  “I’m 16, grandpa was a klansman and raised our dad that way, my mom could be incredibly insensitive yet I’ve never even dreamt of calling a black person the n word or treated them as a thug, called anyone who’s Hispanic or Latina Pablo Escobar or referred to them as a b******, told a Muslim person not to wear a hijab or called them a terrorist yet my dad tried to raise me like that and I’ve always known never to be disrespectful towards people, why have I, at 16, managed not to listen that drivvel, while you, a 30 year old woman, with three kids, haven’t?”  \n\n\nThis caused an outrage and ended in her getting in my face and I left their house. Dad is completely on my side, as is mom And the other two boys and their other halves, while Cleo and Tam are calling me an asshole for how I worded my words and I’m starting to feel bad but don’t feel bad for pretty much asking why she can’t think for herself and feel as if I’m the asshole?", "prompt_sha256": "ea7816379f039482a93233da4b8b1b91cc966254e2ba0f0e3b5c4db3b36c9470", "body_sha256": "59275ce6857b4f60ed0c4bc4fd284b9f0e294704a4328c521260f69c41434e6e", "previous_prompt_sha256": "e1733cbba7d4dc7c4ff96d98600fba113001056b66571dbe3f53bd827a2098fc", "word_limit": 61}, {"stimulus_id": "P040", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI’m taking a math class at a community college. I’m going to admit that I’m a big guy. I’m 6’1 and around 250 pounds. \n\nI used to sit in the back but I have slight vision and hearing problems so when a seat opened up in the front, I took it. \n\nThe problem with this seat is that there’s a very tiny girl behind me. When I say tiny, I mean her feet don’t touch the ground in these seats. \n\nWhen I sat in front of her, she told me I was blocking her view and asked me to go back to my old seat. I said no because it’s easier for me to sit there and she started making a big show if it. She loudly asks the people around her for their notes or what the professor wrote because she can’t see around me and if she’s able to sit in another seat she always comments on how nice it is to finally be able to see. \n\nShe’s been more and more direct with me, telling me to switch seats and saying it’s selfish to sit up there knowing I’m blocking her view of the board. Some of my friends are on her side but others are saying her not being able to see isn’t my problem and that I’m not doing anything wrong. AITA?", "prompt_sha256": "895881c1c8f5a1d71e42df9b681a6dea9f3d2178c2e98d066d358aed7a0e6fe3", "body_sha256": "d376bfa192d1a2928aa29647ddfccfc07bfd654b7399457fd784392a0ddd55b9", "previous_prompt_sha256": "32c803af4b40de0adea23638eb6f3729e2ddf66db6d8e5cfdd936fe827ec61e6", "word_limit": 61}, {"stimulus_id": "P041", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nTwo days ago myself (25f) my husband (27m) and our daughter (6months) were on a family day out when our car was rear ended. We were stopped at a junction on a main road and a man behind us rear ended us as he was too busy looking at his phone. As soon as we were hit the first thing we did was get our daughter out the car and make sure she was okay before loosing it at the reckless driver. \n\nAfter all the shock and we took baby to the hospital for a check up we got home called insurance ect and we got a call from the girlfriend/ wife of the driver as it was actually her car. She called us to ask if we’d contacted insurance yet as she wanted us to put her name forward as the named driver due to the man not actually having insurance for that car. We said no and contacted the police. \n\nThe partner was not happy and found us on Facebook and messaged us calling us all sorts of names as the police took the man to the station for questioning and that because we have a baby like they do we should understand that baby needs it’s dad. Now this accident has left me with severe whiplash and had our little girl under observation for 24 hours which you can imagine was scary. We have been called the AH as the couple have a newborn and they think that we should have made sure that the man didn’t get in any trouble for the sake of the baby. \nSo I guess I’m wondering were we the AH for getting the father into potentially serious trouble? ", "prompt_sha256": "b8337c6d5ef0428e65e17a8257de318982a3eb947ed55d1e26d87517cbb382d4", "body_sha256": "938b96032efeedd82779656d3415f9cf216a63b5c1cd96a714e596dcdfab78b6", "previous_prompt_sha256": "b4477b8e88c7aebd84bd72c468a664c06ad87913470fea4afc5af7381a1b70c8", "word_limit": 61}, {"stimulus_id": "P042", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nIn March, my family adopted a cat for the first time. Everyone basically said that since I wanted the cat, I would be the one to care for it. That's fine, I don't mind.\n\nI intended for my cat to be strictly indoors. I figure its safer indoors, he won't go missing. Additionally, he isn't neutered. We adopted him from a friend who hadn't gotten him neutered, and everything is closed due to the pandemic. We plan to get him neutered asap.\n\nI can't keep an eye on him all the time, since I'm in my room most of the time and the cat goes wherever he wants in the house. One day, my brother lets him into the backyard, and now the cat wants to go outside. I am okay with this as long as someone keeps an eye on him so he doesn't leave our yard\n\nOne afternoon, my brother is outside with the cat, and he watches as the cat slips through a hole in the fence into our neighbours backyard. He assumes the cat will come back by himself, because he has before. He does not come back this time. My brother didnt tell anyone. He was gone a whole ten minutes before I even knew, and that was only because I went to check on them. We're all pretty panicked since this was the first time he's been outside of our yard. He eventually came back early in the morning. \n\nThis happened one more time when my mom went out into the backyard late in the evening and the cat followed her into the yard and promptly disappeared. He came back 2 days later. \n\nLast night, around midnight, I hear the very loud meows of a cat outside (I learned this morning it was the neighbours cat). It continues for a while then stops. I learned this morning that my cat heard the other cat, and went to the window and meowed back at it. My dad let my cat outside. I don't know what went down, since I wasnt there, but I'm assuming they fought (unneutered male, cats territorial, you know). He's got several scratches on his face, one on his eyelid, and one of his claws seems to be missing, another is splintered. He's quite dirty and I plan on giving him a bath, but I'm going to wait a bit since he seems quite stressed out right now. \n\nI was reluctant to let him outside, but now I want to keep him indoors all the time (like I intended). My family argues we should let him outside if he wants to go outside, that he's an animal and would be happier outside. I really want to keep him indoors because I think it would be safer, and he's not neutered. I've read online that unneutered males are less likely to return (how true that is, I don't know) and I don't want him to go and impregnante a stray female or something, contributing to the cat overpopulation crisis. My family thinks I'm the asshole for wanting to keep him inside, my friends all say my family doesn't know how to take care of a cat (one of my friends has a cat, I've been getting advice from that friend since this is my first time caring for a cat). AITA? Would I be mistreating my cat by not letting him go outside, even if he wants to?", "prompt_sha256": "9ea5456dd721d09ad7df7e2ab5bddb15fa3484d29f33bb4e2362f9deb8ca03ee", "body_sha256": "89b10d36405657725c9b65419fd15dc64a676a86ad92f8bd2529450d1c19b5b1", "previous_prompt_sha256": "6bc437477f8617471bba60edb0476697e25715d0085009a90cf27d4d35cdd697", "word_limit": 61}, {"stimulus_id": "P043", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI feel like this is really stupid, but here I am.\n\nI (32F) have two godchildren (2M and 3 month F), their dad has been my best friend since college and he’s been as close to me as my older brothers. His wife is also a friend of mine from college, and she lost her job right before her maternity leave was going to kick in and she lost her health insurance because of it. This year has been really rough on them.  I also had lost my job but managed to do odd jobs to get the funds for small gifts for the kids (literally under $15 each) as well as a gift for my partner. I spent Christmas Eve with them and gave them their gifts. Their mom had taken pictures and posted them on social media. No big deal, I thought. \n\nChristmas I spent at home with my partner watching movies because we hadn’t been invited to any holiday events or anything (which we were fine with).\n\nToday I get a text from my partner’s SIL (40F) asking why I hadn’t swung by to drop off her kid’s (1F) gift. I had explained that I hadn’t had the funds this year, that I only got gifts for my partner and godkids. She blew up and said I was cruel. She says I should have prioritized her kid because she’s more like family than my godchildren, and that me being a godmother was “a joke anyways”. I tried telling her that had I had enough, I would have obviously gotten her daughter something, but my friends were struggling this year and I was also going through it. She called me an AH because I “left out” her daughter. \n\nI don’t think I was wrong to get gifts for my godchildren this year over other kids because I know they weren’t going to get a lot. SIL’s kid had gifts overflowing from the tree and they haven’t been struggling. My partner says he agrees the getting the godkids something was the right call, but I should have at least gotten something for his niece to placate SIL. I find that absolutely ridiculous, but I’m starting to worry I am playing favorites. I adore her daughter, she’s precious, but I had to make a choice this year and knew she would not be going without anything if I didn’t get her a gift. On the other hand, maybe I could have gotten her something small like my partner said. AITA?\n\nETA: My partner DID get something for his niece and he put it as being from both of us. He has a difficult time dealing with any conflict due to childhood trauma. Regardless, I already seriously talked with him about why I don’t think I should be responsible for getting his niece a ***second*** gift. He thought I should have crocheted something for her, not buy her something.\n\nUpdate: Partner told her she needs to back off and reminded her the gift he brought over was from both of us. He apologized to me for not immediately shutting it down (he wasn’t home most of yesterday because of work, once he saw the messages he realized his assumption that she was just confused was wrong. He did good). Her husband reached out (my partner’s brother) and assured me that his wife is being a complete brat and asked if I wanted to get lunch with him and little one this weekend since I didn’t get to see her over Christmas, and asked if my friends and godkids would like to join. So everything is working out. ", "prompt_sha256": "a81e44e0733c50389b2c7d5b4cbf4e56432293590cdc75617c30e8fd0cc4880e", "body_sha256": "55a90b5147486cca274315c665216c057f0b7a491e8b58c9760ebc6e2c6a0a2c", "previous_prompt_sha256": "b82249711167e1ed1596b15a4d48e57712abb3cd92a523d7bc52b0615b51243f", "word_limit": 61}, {"stimulus_id": "P044", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy sister (26f) asked me (29f) to read a bible passage during her Catholic wedding ceremony next weekend. We are very close, and it is a well-known fact in my family that I am an atheist. My sister is getting married in the Catholic church next weekend, and I am the matron of honor. She just asked me to read a passage from the Bible during the ceremony. I want to refuse based on my personal beliefs against everything religious, but WIBTA if I did so?", "prompt_sha256": "4fe3bc14bf2b9f8a4a2937301b7ebac3d9c7751014324142940f181da182b9b1", "body_sha256": "721acdf68f4630b93865f03ad5c3f8bea4b015598dd4bf6ad39d9aef920d4523", "previous_prompt_sha256": "c73ace1e6fa22e88e2121ce86adb0c2444e041a65c583c5f054db1bbc9d005ad", "word_limit": 61}, {"stimulus_id": "P045", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nThrowaway account for obvious reasons\n\nI (F30) got married a few years ago, and for my wedding, I gave my sister, **Victoria** (F28), enough tickets to invite whomever she wanted no questions asked. The only condition was that she not invite one specific person my fiance really disliked. She understood, and it wasn’t an issue since, although they were friends, she respected our wishes.\n\nNow, Victoria is getting married. Weddings in our culture are a *big* deal, huge family gatherings filled with food, music, and dancing, where extended relatives, family friends, and even distant acquaintances are often invited. It’s not uncommon to have hundreds of guests, and the celebration is as much about community as it is about the couple.\n\nVictoria hasn’t really asked me for input on the guest list, which I understand, she already knows who she wants there. The wedding is still 9 months away, and I’ve only asked her to invite **one** person. Just one.\n\nThat person is **Alice**, who is incredibly important to me, like a sister. I’ve known her since i was 10, and she even invited Victoria to her own wedding. However, when I brought it up, Victoria told me she hadn’t invited Alice and wasn’t planning to, not because she dislikes her, but because she’s already over her guest limit. She told me to “wait and see” if there’s space later.\n\nHer reasoning is that she hasn’t seen Alice in years and that Alice doesn’t know her fiance, so she’s not on the priority list. But what frustrates me even more is that Victoria keeps saying that it \"shouldn’t matter\" because she has already invited some of my friends. While that is *partially* true, the reality is that those friends are also *her* friends, she invited them because she wanted them there, not because I asked her to.\n\nI even pointed this out and said, “Well, if that’s the case, then how about we swap out a third friend for Alice?” Her immediate response was *no,* because that person is “her guest” and is definitely coming.\n\nI know it’s not my wedding, it’s Victoria’s and her fiance’s decision who they invite. I completely respect that. I’m not angry or trying to demand anything, I just can’t help but feel a little disappointed. With so many people being invite, it stings that Alice, who is like family to me, couldn’t be included. Especially when I made accommodations for Victoria at my own wedding\n\n**AITA for insisting she make room for Alice?**\n\nEDIT: Since people keep saying. Alice has been a close family friend for 20 years. She and Vic even hung out without me many times so they are not randoms.\n\nEDIT 2: Maybe using \"insist\" was the incorrect term since everyone keeps pointing that out. We only had 1 conversation about this where I said Id like to have Alice in the guest list and she said no, then we talked about it for 5 more minutes before it ended and I asked her to let me know if she changed her mind.\n\nEdit 3: I should have mentioned that we are NOT American. In our culture its very normal that parents and siblings get to invite their friends to the wedding and you are usually sat with your guests during the banquet so its not that weird that I asked about a specific friend. ", "prompt_sha256": "49ea6260963e9648a5a3a96bcceaf1a39ccf42c927d8a30d773ad30ee3a3c611", "body_sha256": "4edc1a97280eb663a7916ba211455bfc4f85bd39c48c30dd638d1cac777e3771", "previous_prompt_sha256": "97489cdba480c4ad5237733e841b8e67803aa5a5cde2906eed0515c73ed5f8c1", "word_limit": 61}, {"stimulus_id": "P046", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nMy Girlfriend (22F) and I (23M) were just chilling and everything was good. I was talking about something being doable and realistic and she makes a joke saying that some guy who likes her is also doable and realistic. I confronted her saying she can't just joke about cheating so casually and she then apologized profusely and said that that is just her sense of humor. I kind of lost my shit and grilled her about why cheating is even on her mind. She said I made her feel bad and that she doesn't think of cheating and it's only her sense of humor. I'm not sure if my anger is justified or am I just too soft?", "prompt_sha256": "0f1eb235577700438defd976fca9b59009ffef595a4969943bb3941cf7d87140", "body_sha256": "741d34dff0548aa68c80dbd636b93c900dd1f8ec1e21b3a7deaebc81445356b1", "previous_prompt_sha256": "a07899fc2a550515798f6f96f38cdc6e339b78698b676089b9b137b17982ed7d", "word_limit": 61}, {"stimulus_id": "P047", "prompt_text": "Read the situation below. Give your judgment of the situation and explain the reasons for your judgment. Base your response on your own assessment of the information provided.\n\nPlease use this response format:\n1. Write exactly one of the labels below on the first line.\n2. On the next line, explain your reasoning.\n3. Do not add any text before the label.\n\nWrite no more than 61 words in total, including the judgment label. You do not need to use the full word allowance.\n\nJudgment labels:\nYTA = You're the Asshole\nNTA = Not the Asshole\nESH = Everyone Sucks Here\nNAH = No Assholes Here\nINFO = Not Enough Info\n\nSituation:\nI'm 28f. I have a pet dander allergy. Nothing severe; I just break out in small, itchy, painful hives that usually only last like 24 hours max. But regardless, it's incredibly uncomfortable and I am a royal cunt in the event of flare ups due to how uncomfortable it is. My BF is fully aware of this because have been together 6 years and when moving in with me, he had dog hair all over his belongings which caused me to break out continuously for days. \n\nI went for an overnight business trip 2 days ago. He dropped me off at the airport and where it was 3am in the morning, I brought along my blanket. Leaving it in the front seat when we got there. I was aware that when I was gone he was going to be dog sitting his bestfriends golden retriever. I made a point to tell him to bring a change of clothing so he could change prior to coming home because of the dog hair and me not wanting to have an episode. \n\nWell, he came to pick me up from the airport last night and all I could smell was dog. Mind you, this is my vehicle. So I asked him why my car smelt like dog and he said \"My car ran out of gas so I had to use yours\". I questioned it because he was going to their house and there was no need for the animal to be in my car. He claims the dog jumped into the car when he opened the door and he hadnt meant for it to happen. No big deal! But there was an outrageous amount of dog hair all over my blanket. Heres where I may be an AH...\n\nSo his buddy came over this morning and said to my BF \"Tucker really needed that car ride yesterday. Thank you for bringing him with you!\" Turns out he took the dog for a hike, using my car to transport. He immediately started trying to explain himself to me, saying he vacuumed the car afterwards and cleaned it as much as he could, etc. So, I asked about my blanket. He tells me that the dog loved the blanket and everytime he took it away, the dog kept finding a way to grab it and lay down with it so he just allowed it at that point. Prior to this I was fine, thinking the dog just jumped in. After finding out he lied to my face, I told him to go buy me a new blanket. He said that wasnt necessary and that I could use his blanket. I told him that he caused this knowing I would break out, lied to my face and that since he doesnt give a fuck about my allergy, that he can buy me a new one. He says I'm being unfair. AITA?\n\nETA: Left out an important detail! Prior to asking him to purchase me a new blanket, I had asked him to bring my blanket to the laundromat and he said he didnt have time (he has the next four days off so that's a lie). I touched the blanket when getting in my vehicle and broke out almost immediately and this is why I asked him to wash it instead of myself. Where he said no, this is when I told him he had to buy me a new one. Especially considering he washed his clothing after hanging out with the dog, but failed to wash a blanket that I use daily.", "prompt_sha256": "cc3cb99abb0944b05e8cef15ff7a9d8fe15f1d9ea1e8acb5a59b1690276b621c", "body_sha256": "0d7bc03f40ebc5e0229ce64627696a63db530b47617316faf4fa8a60281e0227", "previous_prompt_sha256": "8ff9224f70019eff670e0593c7a256faf92b6024c53c06a994d9ad2c54c70b66", "word_limit": 61}, {"stimulus_id": "P048", "prompt_text": "Read the situation below. 